package it.gruppoinit.pal.gp.pay.service.impl;

import java.math.BigDecimal;
import java.util.Set;

import org.apache.commons.lang.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import it.gruppoinit.pal.gp.core.utils.Utilities;
import it.gruppoinit.pal.gp.pay.domain.PayConnectorConfigParams.ConfigParamNames;
import it.gruppoinit.pal.gp.pay.domain.PayDettaglioImporti;
import it.gruppoinit.pal.gp.pay.domain.PayPosizioniDebitorie;
import it.gruppoinit.pal.gp.pay.domain.PayProfiliEntiCreditori;
import it.gruppoinit.pal.gp.pay.service.AvvisiPagoPAService;
import it.gruppoinit.pal.gp.pay.service.PayConnectorConfigValuesService;
import it.gruppoinit.schemas.messages.utilitypagopa.BollettinopagopaRequest;

@Service
public class AvvisiPAgoPAServiceImpl implements AvvisiPagoPAService {

    @Autowired
    private PayConnectorConfigValuesService payConnectorConfigValuesService;

    @Override
    public BollettinopagopaRequest popolaAvvisoRequestDaPosizioneDebitoria(PayPosizioniDebitorie pos, PayProfiliEntiCreditori ente) {

	String codiceSia = payConnectorConfigValuesService.getValoreParametroConfigurazione(ConfigParamNames.CODICE_SIA_ENTE);
	BollettinopagopaRequest r = new BollettinopagopaRequest();
	//	r.setLogoEnte(
	//		"data:image/png;base64,");
	r.setEnteCreditore(ente.getAmministrazione().getAmministrazione());
	if (StringUtils.isNotBlank(ente.getAmministrazione().getIndirizzo())) {
	    String settoreEnte = ente.getAmministrazione().getIndirizzo() + ", ";
	    if (StringUtils.isNotBlank(ente.getAmministrazione().getCap())) {
		settoreEnte += ente.getAmministrazione().getCap() + " ";
	    }
	    if (StringUtils.isNotBlank(ente.getAmministrazione().getCitta())) {
		settoreEnte += ente.getAmministrazione().getCitta() + " ";
	    }
	    if (StringUtils.isNotBlank(ente.getAmministrazione().getProvincia())) {
		settoreEnte += ente.getAmministrazione().getProvincia();
	    }
	    r.setSettoreEnte(settoreEnte);
	}
	String infoEnte = ente.getAmministrazione().getWeb();
	if (StringUtils.isNotBlank(codiceSia)) {
	    infoEnte += "<br />Codice SIA: " + codiceSia;
	}
	r.setInfoEnte(infoEnte);
	r.setCfEnte(ente.getCfEnteQrcodePagopa());
	r.setCbill(ente.getCbill());
	r.setNomeCognomeDestinatario(pos.getSoggettoDebitore().getDenominazioneCompleta());
	r.setCfDestinatario(pos.getSoggettoDebitore().getCfPi());
	r.setIndirizzoDestinatario1(pos.getSoggettoDebitore().getIndirizzoCompleto());
	// r.setIndirizzoDestinatario2("11010 SARRE AO");
	r.setOggettoDelPagamento(pos.getDescrizioneCausale());
	r.setOggettoDelPagamentoBollettino(pos.getDescrizioneCausale());
	r.setOggettoDelPagamentoRata(pos.getDescrizioneCausale());
	r.setImporto(getImporto(pos.getDettagliImporto()));
	r.setData(Utilities.formatDate(pos.getDataScadenza(), false));
	r.setCodiceAvviso(pos.getCodiceAvviso());
	r.setQrCode(pos.getQrCode());
	r.setDelTuoEnte("del tuo ente");
	r.setDataMatrix("abracadabra");
	if (StringUtils.isNotBlank(ente.getCcPostale())) {
	    r.setIntestatarioContoCorrentePostale(ente.getAmministrazione().getAmministrazione());
	    r.setCodiceAvvisoPostale(pos.getCodiceAvviso());
	    r.setDiPoste("di poste"); // TODO
	    r.setNumeroCcPostale(ente.getCcPostale());
	    // r.setDataMatrix("abracadabra");
	    r.setAutorizzazione("NUMERO AUTORIZZAZIONE");// TODO
	}
	return r;
    }

    private String getImporto(Set<PayDettaglioImporti> dettagliImporto) {

	BigDecimal importo = BigDecimal.ZERO;
	for (PayDettaglioImporti i : dettagliImporto) {
	    importo = importo.add(i.getImporto());
	}
	return String.valueOf(importo);
    }
}
